 P.push(A('Hur många fattas till 5?','Det får plats 5 ekollon i raden. Hur många fattas för att den ska bli full?',`<div class="stack">${ff.map(k=>tray(`${five(k)}${eq(`${k} + ${box(5-k,'s')} = 5`,'s')}`,'gap:3cqw;padding:1.6cqw 3cqw')).join('')}</div>`,ff.map(k=>`${k} + ${5-k} = 5`)));
 P.push(A('Tiofältet','Hur många ekollon finns i fältet? Skriv talet.',`<div class="g2x">${[3,7,5,10,8,6].map(n=>`<div style="display:flex;align-items:center;gap:3cqw">${tenFrame(n,28)}${box(n,'s')}</div>`).join('')}</div>`,[3,7,5,10,8,6]));
 const rows=[[1,2,0,4,5,0],[3,0,5,6,0,8],[5,6,7,0,9,0],[0,2,3,0,5,6],[4,5,0,7,0,9]];
 P.push(A('Stenar i rad','Talen går i ordning. Vilka tal fattas på stenarna?',`<div class="stack">${rows.map(rw=>{const st=rw.findIndex(v=>v);const base=rw[st]-st;return tray(rw.map((v,i)=>stone(v||base+i,!v)).join('<span class="step"></span>'),'justify-content:center;gap:1.4cqw;background:#DCE8EC')}).join('')}</div>`,rows.map(rw=>{const st=rw.findIndex(v=>v),base=rw[st]-st;return rw.map((v,i)=>v?null:base+i).filter(x=>x!==null).join(', ')})));
 const down=[[10,9,0,7,0,5],[8,0,6,5,0,3],[6,5,0,3,2,0],[0,4,3,0,1,0],[9,0,7,6,0,4]];
 P.push(A('Räkna baklänges','Ebba hoppar baklänges på stenarna i bäcken. Vilka tal fattas?',`<div class="stack">${down.map(rw=>{const st=rw.findIndex(v=>v);const base=rw[st]+st;return tray(rw.map((v,i)=>stone(v||base-i,!v)).join('<span class="step"></span>'),'justify-content:center;gap:1.4cqw;background:#DCE8EC')}).join('')}</div>`,down.map(rw=>{const st=rw.findIndex(v=>v),base=rw[st]+st;return rw.map((v,i)=>v?null:base-i).filter(x=>x!==null).join(', ')})));
 const r=rng(14),cells=shuffle(r,[...Array(24).keys()]).slice(0,15),kinds=['apple','leaf','mushroom'],cnt={apple:0,leaf:0,mushroom:0};let scn=`<svg viewBox="0 0 120 80" class="svgw" style="border-radius:3cqw;background:var(--tint)">`;
