/* 3D-penna (Recraft) i tre delar: spetsen och änden behåller formen, kroppen sträcks så att pennan blir exakt w cqw lång (spetsen vid noll) */
function pen3d(w,color,h=3.6){const k=/blue/.test(color)?'b':/lingon/.test(color)?'r':/moss/.test(color)?'g':/kant/.test(color)?'o':'b';const P=typeof PEN3D!=='undefined'&&PEN3D[k];if(!P)return null;
 return `<span class="pen3d" style="display:flex;align-items:center;width:${w.toFixed(2)}cqw;height:${h}cqw" aria-hidden="true"><img src="${P.tip}" alt="" draggable="false" style="height:100%;width:${(P.tw*h).toFixed(2)}cqw;flex:none"><img src="${P.body}" alt="" draggable="false" style="height:100%;flex:1;min-width:0"><img src="${P.end}" alt="" draggable="false" style="height:100%;width:${(P.ew*h).toFixed(2)}cqw;flex:none"></span>`}
function pencilBar(cm,color){const p3=pen3d(cm*4.762,color);if(p3)return p3;const W=cm*10;return `<svg class="ic" viewBox="-0.5 0 ${W+1} 14" style="width:${(cm*4.762).toFixed(2)}cqw;height:${(14*.4762).toFixed(2)}cqw" aria-hidden="true"><path d="M0 7 L8 1 L${W-6} 1 L${W-6} 13 L8 13Z" fill="${color}"/><path d="M0 7 L8 1 L8 13Z" fill="var(--a-sand)"/><path d="M0 7 L3 4.8 L3 9.2Z" fill="var(--a-ink)"/><rect x="${W-6}" y="1" width="6" height="12" rx="2" fill="var(--a-rose)"/></svg>`}
function trueRuler(cm=15){let s=`<svg class="ic" viewBox="-0.5 0 ${cm*10+1} 24" style="width:${(cm*4.762).toFixed(2)}cqw;height:${(24*.4762).toFixed(2)}cqw" aria-hidden="true"><rect x="-0.5" y="0" width="${cm*10+1}" height="24" rx="2" fill="#F6E7B8"/>`;for(let i=0;i<=cm*10;i++){const L=i%10===0?9:i%5===0?6:3.5;s+=`<line x1="${i}" y1="0" x2="${i}" y2="${L}" stroke="var(--ink)" stroke-width="${i%10===0?.6:.3}"/>`;if(i%10===0)s+=`<text x="${i}" y="19" font-size="6.5" text-anchor="middle" font-family="Andika,sans-serif" fill="var(--ink)">${i/10}</text>`}return s+'</svg>'}
