 P.push(A('Räkna pengarna','Hur mycket pengar är det? Lägg ihop mynten och sedlarna.',`<div class="g2x">${cs.map(([c,t])=>`<div class="tray" style="flex-direction:column;gap:1.4cqw"><div style="display:flex;gap:1cqw;align-items:center">${c.map(v=>v>=20?noteSvg(v,13):coinSvg(v,8.5)).join('')}</div>${eq(`${box(t+'|'+t+' kr|'+t+'kr','s')} kr`,'s')}</div>`).join('')}</div>`,cs.map(x=>x[1]+' kr')));
 const ex=[[10,2,5],[10,5,2],[5,1,5],[20,10,2],[10,1,10]];
 P.push(A('Byta mynt','Sverige har mynt på 1, 2, 5 och 10 kronor. Hur många mynt behövs för att det ska bli lika mycket?',`<div class="stack" style="gap:1.4cqw">${ex.map(([tot,c,n])=>tray(`<span style="display:grid;place-items:center;width:22cqw">${tot>10?noteSvg(tot,21):coinSvg(tot,10)}</span><span class="eq s" style="font-size:4.2cqw">= ${box(n,'s')} st</span>${coinSvg(c,8)}`,'gap:2.4cqw;padding:1.4cqw 3cqw;justify-content:flex-start')).join('')}</div>`,ex.map(([tot,c,n])=>`${tot} kr = ${n} st ${c}-kronor`)));
 P.push(A('Betala jämnt','Tryck på de mynt du behöver för att betala precis rätt summa. Använd så få mynt som möjligt.',`<div class="stack">${[[7,[[10,0],[5,1],[2,1],[1,0],[1,0]]],[12,[[10,1],[5,0],[2,1],[1,0],[1,0]]],[6,[[10,0],[5,1],[2,0],[2,0],[1,1]]]].map(([p,cs])=>`<div class="tray" style="flex-direction:column;align-items:stretch;gap:1.4cqw"><span class="p">Betala ${p} kr</span><div style="display:flex;gap:1.6cqw;flex-wrap:wrap">${cs.map(([v,ok])=>selOk(coinSvg(v,9),'pick',ok)).join('')}</div></div>`).join('')}</div>`,['7 kr: 5 + 2','12 kr: 10 + 2','6 kr: 5 + 1']));
 /* ungefär riktiga priser (styckpris i en svensk affär) */
 const bc=[[['apple',5],['icecream',15],['egg',3]],[['bread',30],['milk',17],['banana',4]],[['bun',12],['carrot',3],['milk',17]],[['egg',3],['bun',12],['apple',5]]];
 P.push(A('Billigast och dyrast','Läs prislapparna och jämför. Tryck på rätt sak i varje rad.',`<div class="stack" style="gap:1.2cqw">${[[bc[0],'billigast'],[bc[1],'dyrast'],[bc[2],'billigast'],[bc[3],'dyrast']].map(([row,w])=>{const ps=row.map(x=>x[1]),t=w==='billigast'?Math.min(...ps):Math.max(...ps);return `<div class="tray" style="flex-direction:column;align-items:stretch;gap:.6cqw;padding:1.2cqw 3cqw"><p class="p">Tryck på det som är <b>${w}</b>.</p><div style="display:flex;justify-content:space-around">${row.map(([n,p])=>selOk(`<div style="display:flex;align-items:center;gap:1.4cqw">${art(n,9)}${priceTag(p)}</div>`,'pick',p===t)).join('')}</div></div>`}).join('')}</div>`,['billigast: ägget','dyrast: brödet','billigast: moroten','dyrast: bullen']));
 const shop=[['apple',5],['icecream',15],['egg',3],['bread',30],['carrot',3],['milk',17]];
 P.push(A('Har du råd?','Du har 20 kronor. Tryck på allt som kostar 20 kronor eller mindre.',`<div class="g3x">${shop.map(([n,p])=>selOk(`<div class="tray" style="flex-direction:column;gap:1.2cqw;padding:2cqw">${art(n,13)}${priceTag(p)}</div>`,'pick',p<=20)).join('')}</div>`,['äpple, glass, ägg, morot, mjölk']));
