 P.push(A('Hur många kan du köpa?','Räkna pengarna. Hur många kan Ebba köpa för alla pengarna?',`<div class="stack" style="gap:1.3cqw">${hd('1.5fr 1fr .9fr',['Ebba har','Kostar','Hon får'])}${hm.map(([c,n,p])=>tray(`<div style="${g3('1.5fr 1fr .9fr')}"><div style="display:flex;gap:.8cqw;align-items:center">${c.map(money).join('')}</div><div style="display:flex;align-items:center;gap:1.2cqw">${art(n,9)}${priceTag(p)}</div>${eq(`${box(c.reduce((a,b)=>a+b,0)/p,'s')} st`,'s')}</div>`,'padding:1.3cqw 3cqw')).join('')}</div>`,hm.map(([c,n,p])=>`${c.reduce((a,b)=>a+b,0)}/${p} = ${c.reduce((a,b)=>a+b,0)/p} st`)));
