 const rid=[['Jag är större än 5 men mindre än 7.',6],['Om du lägger till 3 till mig blir det 10.',7],['Jag är dubbelt så stor som 4.',8],['Jag är ett jämnt tal mellan 11 och 15, och hälften av mig är 6.',12],['Jag är hälften av 10.',5]];
 P.push(A('Talgåtor','Läs gåtan. Vilket tal är jag?',`<div class="stack">${rid.map(([q,a])=>tray(`<p class="p" style="flex:1">${q}</p>${box(a)}`)).join('')}</div>`,rid.map(x=>x[1])));
 const mush=[[50,10],[63,12],[75,18],[84,28],[88,40],[80,46],[66,48],[60,49],[61,62],[63,76],[64,88],[50,90],[36,88],[37,76],[39,62],[40,49],[34,48],[20,46],[12,40],[16,28],[25,18],[37,12]];
