 P.push(A('Vilken passar inte nu?','Lite svårare. Tryck på den som inte hör ihop med de andra. Kan du säga varför?',`<div class="stack">${odd2.map(([a,o])=>tray(choice(a.map(n=>typeof n==='number'?`<span style="font:400 10cqw/1 var(--f-read);display:block;width:12.5cqw;text-align:center">${n}</span>`:SH[n]?sh(n,SC.b,11):artFit(n,12,11,true)),o),'justify-content:space-around')).join('')}</div>`,['20 (inte i 3:ans tabell)','cirkeln (har inga hörn)','hunden (äter inte gräs)','sandalerna (inte för kyla)']));
